package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for TarUtils.verifyCheckSum
 */
public class TarUtils_verifyCheckSum_TriageGen0Test {

    // Constants based on TAR specification used in TarUtils
    private static final int CHKSUM_OFFSET = 148;
    private static final int CHKSUMLEN = 8;

    /**
     * Helper to create a valid header template.
     * TAR headers are typically 512 bytes.
     */
    private byte[] createBaseHeader() {
        byte[] header = new byte[512];
        Arrays.fill(header, (byte) 0);
        return header;
    }

    @Test
    public void testVerifyCheckSum_ExactMatchUnsigned() {
        byte[] header = createBaseHeader();
        // We need to find a header where computeCheckSum matches the octal at CHKSUM_OFFSET
        // However, since the method replaces the checksum bytes with ' ' (0x20) during calculation,
        // we can simulate the logic: storedSum == unsignedSum

        // Let's build a header where the sum of all bytes (with checksum area as ' ') 
        // equals a specific octal value.

        // 1. Fill some data
        header[0] = 'A'; // 65
        header[1] = 'B'; // 66
        // Sum = 131

        // 2. Set checksum area to ' ' (0x20) to match the logic in the loop
        for (int i = CHKSUM_OFFSET; i < CHKSUM_OFFSET + CHKSUMLEN; i++) {
            header[i] = ' ';
        }

        // 3. The loop replaces header[i] with ' ' for the sum, so unsignedSum will be 131.
        // We need storedSum to be 131. 131 in octal is 203.
        // '0000203' is 7 digits, but method limits to 6 digits or first sequence.
        // Let's use '000203' (which is 0*8^5 + 0*8^4 + 0*8^3 + 2*8^2 + 0*8^1 + 3*8^0 = 128 + 3 = 131)
        header[CHKSUM_OFFSET] = '0';
        header[CHKSUM_OFFSET + 1] = '0';
        header[CHKSUM_OFFSET + 2] = '0';
        header[CHKSUM_OFFSET + 3] = '2';
        header[CHKSUM_OFFSET + 4] = '0';
        header[CHKSUM_OFFSET + 5] = '3';
        header[CHKSUM_OFFSET + 6] = ' '; // To trigger digits > 0 else branch or just end
        header[CHKSUM_OFFSET + 7] = ' ';

        assertTrue("Should return true when storedSum == unsignedSum", TarUtils.verifyCheckSum(header));
    }

    @Test
    public void testVerifyCheckSum_ExactMatchSigned() {
        byte[] header = createBaseHeader();
        header[0] = (byte) 0xFF; // -1 in signed, 255 in unsigned

        // Sum signed: -1. Sum unsigned: 255.
        // If we set storedSum to -1? No, storedSum is long (positive).
        // But if the header contains bytes that result in a signedSum == storedSum.
        // Let's use a byte that is negative.
        header[1] = (byte) 0x80; // -128 signed, 128 unsigned
        // Total signed = -128 + (-1) = -129.
        // This is tricky because storedSum is derived from '0'-'7' which are positive.

        // Let's aim for storedSum == signedSum.
        // If header[0] = 0x01, header[1] = 0x01. Sum = 2.
        header[0] = 0x01;
        header[1] = 0x01;
        for (int i = CHKSUM_OFFSET; i < CHKSUM_OFFSET + CHKSUMLEN; i++) {
            header[i] = ' ';
        }
        header[CHKSUM_OFFSET] = '0';
        header[CHKSUM_OFFSET + 1] = '0';
        header[CHKSUM_OFFSET + 2] = '0';
        header[CHKSUM_OFFSET + 3] = '0';
        header[CHKSUM_OFFSET + 4] = '0';
        header[CHKSUM_OFFSET + 5] = '2';

        assertTrue("Should return true when storedSum == signedSum", TarUtils.verifyCheckSum(header));
    }

    @Test
    public void testVerifyCheckSum_Compress177Condition() {
        byte[] header = createBaseHeader();
        // storedSum > unsignedSum
        // Set checksum to 10 (octal) -> storedSum = 8
        header[CHKSUM_OFFSET] = '0';
        header[CHKSUM_OFFSET + 1] = '1';
        header[CHKSUM_OFFSET + 2] = '0';
        for (int i = CHKSUM_OFFSET + 3; i < CHKSUM_OFFSET + CHKSUMLEN; i++) {
            header[i] = ' ';
        }

        // Set data such that unsignedSum is small
        // header[0] = 0x01. unsignedSum = 1.
        header[0] = 0x01;
        // storedSum = 8. 8 > 1.

        assertTrue("Should return true due to COMPRESS-177 (storedSum > unsignedSum)", TarUtils.verifyCheckSum(header));
    }

    @Test
    public void testVerifyCheckSum_Fail() {
        byte[] header = createBaseHeader();
        // storedSum = 10 (octal) = 8
        header[CHKSUM_OFFSET] = '0';
        header[CHKSUM_OFFSET + 1] = '1';
        header[CHKSUM_OFFSET + 2] = '0';
        for (int i = CHKSUM_OFFSET + 3; i < CHKSUM_OFFSET + CHKSUMLEN; i++) {
            header[i] = ' ';
        }

        // unsignedSum = 100. 8 < 100.
        header[0] = 100;

        assertFalse("Should return false when all conditions fail", TarUtils.verifyCheckSum(header));
    }

    @Test
    public void testVerifyCheckSum_DigitsLimit() {
        byte[] header = createBaseHeader();
        // Test digits++ < 6 limit
        // '0000001' -> 1
        // '0000001' -> digits becomes 7, but loop only processes 6
        header[CHKSUM_OFFSET] = '0';
        header[CHKSUM_OFFSET + 1] = '0';
        header[CHKSUM_OFFSET + 2] = '0';
        header[CHKSUM_OFFSET + 3] = '0';
        header[CHKSUM_OFFSET + 4] = '0';
        header[CHKSUM_OFFSET + 5] = '0';
        header[CHKSUM_OFFSET + 6] = '1'; // 7th digit
        header[CHKSUM_OFFSET + 7] = '1';

        // storedSum should be 0 because digits++ < 6 fails on the 7th digit '1'
        // or rather, the 7th digit is not processed into storedSum.
        // Let's trace: 
        // i=offset: '0' (digits=1, sum=0)
        // i=offset+1: '0' (digits=2, sum=0)
        // i=offset+2: '0' (digits=3, sum=0)
        // i=offset+3: '0' (digits=4, sum=0)
        // i=offset+4: '0' (digits=5, sum=0)
        // i=offset+5: '0' (digits=6, sum=0)
        // i=offset+6: '1' (digits=7, sum stays 0)

        // unsignedSum must be 0 for it to be true.
        // But header is initialized to 0. However, the loop replaces checksum area with ' '.
        // ' ' is 0x20 (32).
        // So unsignedSum will be 32 * 8 = 256.
        // storedSum = 0. 0 < 256.

        assertFalse(TarUtils.verifyCheckSum(header));
    }

    @Test
    public void testVerifyCheckSum_InvalidOctalDigit() {
        byte[] header = createBaseHeader();
        // '8' is not between '0' and '7'
        header[CHKSUM_OFFSET] = '8'; 
        header[CHKSUM_OFFSET + 1] = '1';

        // storedSum should be 0.
        // unsignedSum will be 32 * 8 = 256.
        assertFalse(TarUtils.verifyCheckSum(header));
    }

    @Test
    public void testVerifyCheckSum_DigitsBreakBranch() {
        byte[] header = createBaseHeader();
        // '0' '1' 'X' '2'
        // i=offset: '0' (digits=1, sum=0)
        // i=offset+1: '1' (digits=2, sum=1)
        // i=offset+2: 'X' (not 0-7, digits > 0 is true, digits = 6)
        // i=offset+3: '2' (digits is 6, digits++ < 6 is false, skip)
        header[CHKSUM_OFFSET] = '0';
        header[CHKSUM_OFFSET + 1] = '1';
        header[CHKSUM_OFFSET + 2] = 'X'; 
        header[CHKSUM_OFFSET + 3] = '2';

        // storedSum = 1.
        // unsignedSum = 32 * 8 = 256.
        assertFalse(TarUtils.verifyCheckSum(header));
    }
}
